+            return whiteBox.isMethodCompiled(testMethodRef) || whiteBox.isMethodQueuedForCompilation(testMethodRef);
+        });
+        waitForCondition("compilation (dequeue)", () -> !whiteBox.isMethodQueuedForCompilation(testMethodRef));
