+        final var result = new Object() { boolean value = false; };
+        Utils.waitForCondition(() -> {
+                if (!result.value) {
+                    System.out.println("Running: " + name);
+                    result.value = condition.getAsBoolean();
+                }
+                return result.value;
+            },
+            STAGE_TIME_LIMIT_SEC > 0 ? STAGE_TIME_LIMIT_SEC * 1000 : -1
+        );
